CREDIT_LINE = "DEVELOPED BY ENG NJEIMI HAYTHAM - PROBUILD TRACKER"


def footer():
    st.markdown(f"<div class='credit-footer'>{CREDIT_LINE}</div>", unsafe_allow_html=True)


def get_base_url():
    return st.secrets.get("app_base_url", "https://your-app.streamlit.app")


# =========================================================
#                     CLIENT VIEW
# =========================================================
def render_client_view(panel_id: str):
    meta = storage_utils.load_panel_metadata(panel_id)
    if meta is None:
        st.markdown("<div class='sharq-header'><h1>SHARQ PROBUILD</h1></div>", unsafe_allow_html=True)
        st.error("Panel not found. Please contact the technical department.")
        footer()
        return

    st.markdown(
        f"""<div class="sharq-header">
        <h1>SHARQ PROBUILD</h1>
        <p>Panel: <b>{meta.get('panel_name','')}</b> &nbsp;|&nbsp; ID: {panel_id}</p>
        </div>""",
        unsafe_allow_html=True,
    )

    # ---- Warranty countdown ----
    install_date = datetime.fromisoformat(meta["install_date"])
    warranty_end = install_date + timedelta(days=30 * int(meta["warranty_months"]))
    days_left = (warranty_end - datetime.now()).days

    if days_left >= 0:
        st.markdown(
            f"""<div class="warranty-box">
            <div>Warranty Status</div>
            <div class="days">{days_left} days left</div>
            <div>Expires on {warranty_end.strftime('%Y-%m-%d')}</div>
            </div>""",
            unsafe_allow_html=True,
        )
    else:
        st.markdown(
            f"""<div class="warranty-box" style="background:#7a1f1f;">
            <div>Warranty Status</div>
            <div class="days">EXPIRED</div>
            <div>Ended on {warranty_end.strftime('%Y-%m-%d')}</div>
            </div>""",
            unsafe_allow_html=True,
        )

    # ---- PDF download ----
    st.markdown("<div class='panel-card'>", unsafe_allow_html=True)
    st.write("**Electrical Panel Diagram**")
    pdf_bytes = storage_utils.get_file_bytes(meta["pdf_path"])
    st.download_button(
        "Download Panel Diagram (PDF)",
        data=pdf_bytes,
        file_name=f"{panel_id}_diagram.pdf",
        mime="application/pdf",
        use_container_width=True,
    )
    st.markdown("</div>", unsafe_allow_html=True)

    # ---- WhatsApp support ----
    wa_number = st.secrets.get("support_whatsapp_number", "")
    if wa_number:
        wa_text = f"Hello, I need support for panel {panel_id} ({meta.get('panel_name','')})."
        wa_url = f"https://wa.me/{wa_number}?text={wa_text.replace(' ', '%20')}"
        st.link_button("💬 Contact Technical Support (WhatsApp)", wa_url, use_container_width=True)

    st.divider()

    # ---- Grounded AI Assistant ----
    st.write("**Ask about this panel's parts**")
    st.caption("Answers are strictly based on the approved technical data for this panel only.")

    if "chat_history" not in st.session_state:
        st.session_state.chat_history = []

    for role, msg in st.session_state.chat_history:
        with st.chat_message(role):
            st.write(msg)

    question = st.chat_input("e.g. How many pieces of part X are in the panel?")
    if question:
        st.session_state.chat_history.append(("user", question))
        with st.chat_message("user"):
            st.write(question)

        excel_rows = storage_utils.get_excel_rows(meta["excel_path"])
        pdf_context = storage_utils.get_pdf_context(meta["pdf_path"])

        with st.chat_message("assistant"):
            with st.spinner("Checking approved technical data..."):
                answer = ai_assistant.ask_local(
                    question=question,
                    excel_rows=excel_rows,
                    pdf_text=pdf_context,
                )
            st.write(answer)
        st.session_state.chat_history.append(("assistant", answer))

    footer()


# =========================================================
#                     ADMIN VIEW
# =========================================================
def render_admin_view():
    st.markdown(
        """<div class="sharq-header"><h1>SHARQ PROBUILD</h1>
        <p>Technical Panel Management Dashboard</p></div>""",
        unsafe_allow_html=True,
    )

    if "is_admin" not in st.session_state:
        st.session_state.is_admin = False

    if not st.session_state.is_admin:
        with st.form("login_form"):
            pwd = st.text_input("Admin Password", type="password")
            submitted = st.form_submit_button("Login", use_container_width=True)
        if submitted:
            if pwd == st.secrets.get("admin_password", ""):
                st.session_state.is_admin = True
                st.rerun()
            else:
                st.error("Incorrect password.")
        footer()
        return

    tab_new, tab_list = st.tabs(["➕ New Panel", "📂 Existing Panels"])

    with tab_new:
        st.subheader("Register a New Panel")
        with st.form("new_panel_form", clear_on_submit=True):
            panel_name = st.text_input("Panel Name / Number *")
            warranty_months = st.number_input("Warranty Duration (months)", min_value=1, max_value=120, value=12)
            install_date = st.date_input("Installation Date", value=datetime.now())
            excel_file = st.file_uploader(
                "Parts List (Excel: Part Number, Description, Quantity) *", type=["xlsx", "xls"]
            )
            pdf_file = st.file_uploader("Panel Diagram (PDF) *", type=["pdf"])
            submitted = st.form_submit_button("Create Panel + Generate QR", use_container_width=True)

        if submitted:
            if not (panel_name and excel_file and pdf_file):
                st.error("Please fill all required fields and upload both files.")
            else:
                ok, err = excel_utils.validate_excel(excel_file)
                if not ok:
                    st.error(f"Excel file is invalid: {err}")
                else:
                    with st.spinner("Uploading to Google Drive and generating panel..."):
                        panel_id = storage_utils.create_panel(
                            panel_name=panel_name,
                            install_date=install_date.isoformat(),
                            warranty_months=warranty_months,
                            excel_file=excel_file,
                            pdf_file=pdf_file,
                        )
                    client_url = f"{get_base_url()}/?panel={panel_id}"
                    qr_img = qr_utils.generate_qr(client_url)
                    st.success(f"Panel '{panel_name}' created successfully. ID: {panel_id}")
                    st.image(qr_img, caption="Scan to open the client page", width=220)
                    st.code(client_url)
                    st.download_button(
                        "Download QR Code (PNG)",
                        data=qr_utils.image_to_bytes(qr_img),
                        file_name=f"{panel_id}_qr.png",
                        mime="image/png",
                    )

    with tab_list:
        st.subheader("All Registered Panels")
        panels = storage_utils.list_panels()
        if not panels:
            st.info("No panels registered yet.")
        for p in panels:
            with st.expander(f"{p['panel_name']}  ·  {p['panel_id']}"):
                client_url = f"{get_base_url()}/?panel={p['panel_id']}"
                st.write(f"Installed: {p['install_date']}  |  Warranty: {p['warranty_months']} months")
                st.code(client_url)
                qr_img = qr_utils.generate_qr(client_url)
                st.image(qr_img, width=150)

    footer()


# =========================================================
#                        ROUTER
# =========================================================
panel_param = st.query_params.get("panel")
if panel_param:
    render_client_view(panel_param)
else:
    render_admin_view()
